            report_fail_msg(
                "sve512_stencil_axis_arm: stencil axis kernel SDC detected");
            return EXIT_FAILURE;
        }
    } while (test_time_condition(test));

    return EXIT_SUCCESS;
}

static int sve512_stencil_axis_arm_cleanup(struct test *test)
{
    delete static_cast<SveStencilAxisData *>(test->data);
    return EXIT_SUCCESS;
}

