 * into z2 survive, and does predicated merging FMLA accumulate correctly?
 * Build: clang -static -O2 -march=armv9-a+sve -o sve_fmla_isolate .c */
#include <stdio.h>

int main(void)
{
    double a[4] = {1, 2, 3, 4};
    double b[4] = {2, 2, 2, 2};
    double z2_direct[4] = {0};
    double z2_fmla[4] = {0};
    double z2_fmuladd[4] = {0};

    /* 1. MOV (SVE immediate) alone: does z2 = 1.0 survive a store? */
    asm volatile(
        "ptrue p0.d\n"
        "mov   z2.d, #1\n"
        "st1d  z2.d, p0, [%0]\n"
        : : "r"(z2_direct) : "z2", "p0", "memory");
    printf("mov z2.d,#1  -> [%.1f %.1f]\n", z2_direct[0], z2_direct[1]);

    /* 2. MOV then predicated merging FMLA (z2 += a*b) */
    asm volatile(
        "ptrue p0.d\n"
        "mov   z2.d, #1\n"
        "ld1d  z0.d, p0/z, [%0]\n"
        "ld1d  z1.d, p0/z, [%1]\n"
        "fmla  z2.d, p0/m, z0.d, z1.d\n"
        "st1d  z2.d, p0, [%2]\n"
        : : "r"(a), "r"(b), "r"(z2_fmla)
        : "z0", "z1", "z2", "p0", "memory");
    printf("fmla(m,ptrue) -> [%.1f %.1f] (expect [3.0 5.0])\n",
           z2_fmla[0], z2_fmla[1]);

    /* 3. FMUL then FADD (separate ops) as the double-rounding contrast */
    asm volatile(
        "ptrue p0.d\n"
        "mov   z3.d, #1\n"
        "ld1d  z0.d, p0/z, [%0]\n"
        "ld1d  z1.d, p0/z, [%1]\n"
