        REPORT("P3 fmla merging (ptrue)", ok, "acc = 1 + (i+1)*2 all lanes");
    }

    /* ---- P4: ld1d/st1d round-trip integrity at full VL ---- */
    {
        double a[32], r[32];
        for (int i = 0; i < 32; ++i) a[i] = 0.5 * i + 0.25;
        svst1_f64(svptrue_b64(), r, svld1_f64(svptrue_b64(), a));
        int ok = 1;
        for (uint64_t i = 0; i < lanes && i < 32; ++i)
            ok &= (r[i] == a[i]);
        char d[64];
        snprintf(d, sizeof d, "%lu lanes bit-identical", lanes);
        REPORT("P4 ld1d/st1d roundtrip", ok, d);
    }

    /* ---- P5: SME ZA storage round-trip (SVL-dependent) ---- */
    {
        /* ONE tile slice via ZERO + readout. SME asm: smstart za; zero
         * {za}; write one f64 slice via MOV to ZA is arch-encoded — the
         * portable probe uses the f64 tile MOVA-free path: zero then read
         * a slice with za readout must give 0 everywhere; then a full
         * FMOPA round-trip (P6) covers non-zero storage. */
        int64_t svl = 0, zero_ok = 1;
        asm volatile(
            "smstart za\n"
            "rdsvl %0, #1\n"
            "zero {za}\n"
            "smstop za\n"
            : "=r"(svl));
        REPORT("P5 SME zero+rdsvl", svl > 0 && (svl & (svl - 1)) == 0,
               "rdsvl power-of-2 bytes > 0");
        (void)zero_ok;
    }

    /* ---- P6: SME FMOPA vs single-rounding fmaf (F4 record) ---- */
    {
        /* 2x2 f64 outer-product accumulate: za_tile[j][i] += a[j]*b[i].
         * gem5 implements FMOPA as fplibMul + fplibAdd (double rounding);
         * hardware is single-rounding. We record whether THIS simulator's
         * FMOPA matches fmaf on bit-dense operands (0.1 is inexact, so
         * the two roundings can differ by 1 ulp). */
        double a[2] = {0.1, 0.30000001};
        double b[2] = {0.20000001, 0.7};
        double tile[2][2] = {{0}};
        asm volatile(
            "smstart za\n"
            "ptrue p0.d\n"
            "ld1d z0.d, p0/z, [%2]\n"      /* a in z0 (2 lanes at SVL>=128) */
            "ld1d z1.d, p0/z, [%3]\n"      /* b in z1 */
            "fmopa za0.d, p0/m, p0/m, z0.d, z1.d\n"
            "read za0.d { z2.d[p0, 0] }, p0\n"   /* read row 0 */
            "read za0.d { z3.d[p0, 1] }, p0\n"   /* read row 1 */
            "st1d z2.d, p0, [%0]\n"
            "st1d z3.d, p0, [%1]\n"
            "smstop za\n"
            : : "r"(tile[0]), "r"(tile[1]), "r"(a), "r"(b)
            : "z0", "z1", "z2", "z3", "p0", "memory");
        double ref[2][2];
        for (int j = 0; j < 2; ++j)
            for (int i = 0; i < 2; ++i)
                ref[j][i] = fmaf(a[j], b[i], 0.0);
        int bitexact = 1;
        for (int j = 0; j < 2; ++j)
            for (int i = 0; i < 2; ++i)
                bitexact &= (tile[j][i] == ref[j][i]);
        char d[160];
        snprintf(d, sizeof d,
                 "fmopa==fmaf bitexact=%d tile[0][0]=%.17g ref=%.17g "
                 "(diff path => F4 double-rounding)", bitexact, tile[0][0],
                 ref[0][0]);
        REPORT("P6 fmopa vs fmaf (F4)", 1 /* recorded, not judged */, d);
    }

    printf("RESULT: %d deviation(s) beyond the recorded ones\n", deviations);
    return deviations ? 2 : 0;
}

