37	    size_t vc = (size_t)rounds * n, nn = (size_t)n * n;
38	    std::vector<float> a(vc), b(vc);
39	    std::vector<float> golden(nn, 0.0f), golden2(nn, 0.0f);
40	    for (size_t i = 0; i < vc; ++i) {
41	        a[i] = frand_scale_f(1.125f) - 0.5625f;
42	        b[i] = frand_scale_f(1.125f) - 0.5625f;
43	        CHECK(std::isfinite(a[i]) && std::fabs(a[i]) < 0.5625f, "fmopa |a|<0.5625");
44	        CHECK(std::isfinite(b[i]) && std::fabs(b[i]) < 0.5625f, "fmopa |b|<0.5625");
45	    }
46	    for (long k = 0; k < rounds; ++k)
47	        for (long r = 0; r < n; ++r)
48	            for (long c = 0; c < n; ++c)
49	                golden[(size_t)r * n + c] = std::fmaf(
50	                    a[(size_t)k * n + r], b[(size_t)k * n + c],
51	                    golden[(size_t)r * n + c]);
52	    // Independent recompute (same op order) must be bit-identical.
53	    for (long k = 0; k < rounds; ++k)
54	        for (long r = 0; r < n; ++r)
55	            for (long c = 0; c < n; ++c)
56	                golden2[(size_t)r * n + c] = std::fmaf(
57	                    a[(size_t)k * n + r], b[(size_t)k * n + c],
58	                    golden2[(size_t)r * n + c]);
59	    CHECK(0 == memcmp(golden.data(), golden2.data(), nn * sizeof(float)),
60	          "fmopa golden self-consistent (bit-exact recompute)");
61	    // 64-step sums must stay finite and below 21.
62	    for (size_t i = 0; i < nn; ++i) {
63	        CHECK(std::isfinite(golden[i]) && std::fabs(golden[i]) < 21.0f,
64	              "fmopa 64-step sum < 21");
65	    }
66	}
