75	            size_t ij = (size_t)i * n + j;
76	            a[ij] = (double)((r64() % 1024) * 64 + (i * n + j));
77	            b[ij] = (double)((r64() % 1024) * 64 + (i * n + j));
78	            distinct.insert(a[ij]);
79	            distinct.insert(b[ij]);
80	        }
81	    CHECK(distinct.size() == (size_t)n * n * 2, "za_tileview all-distinct (a and b)");
