87	static const size_t RADIUS = 6, B_TILE = 16, coord = 10, extent = 56,
88	                    stride = 64;
89	static const size_t ITER = 100000000;
90	
91	static void stencil_expected(const std::vector<double> &src, double out[B_TILE])
92	{
93	    const double *s = src.data() + coord * stride * B_TILE;
94	    for (size_t j = 0; j < B_TILE; ++j) out[j] = 0.0;
95	    for (size_t r = 1; r <= RADIUS; ++r) {
96	        std::ptrdiff_t off = (std::ptrdiff_t)(r * stride) * B_TILE;
97	        for (size_t j = 0; j < B_TILE; ++j) {
98	            double delta = 0.0;
99	            if (coord >= r) delta += s[-off + (std::ptrdiff_t)j];
100	            if (coord + r < extent) delta += s[+off + (std::ptrdiff_t)j];
101	            out[j] += 0.125 * delta;
102	        }
103	    }
104	    for (size_t j = 0; j < B_TILE; ++j) out[j] *= (double)ITER;
105	}
