107	static void stencil_check(bool fixed_src)
108	{
109	    std::vector<double> src(extent * stride * B_TILE);
110	    for (size_t i = 0; i < src.size(); ++i)
111	        src[i] = fixed_src ? (double)(i % B_TILE + 1) : (double)(1 + r32() % 256);
112	    double expected[B_TILE];
113	    stencil_expected(src, expected);
114	    if (fixed_src) {
115	        // Degenerate case: must reproduce the original analytic formula
116	        // bit-exactly.
117	        for (size_t j = 0; j < B_TILE; ++j) {
118	            double analytic = 1.5 * (double)ITER * (double)(j + 1);
119	            CHECK(expected[j] == analytic, "stencil ref == analytic on fixed src");
120	        }
121	    } else {
122	        // Random case: expected stays an exact 1/8-grid value below 2^53.
123	        for (size_t j = 0; j < B_TILE; ++j) {
124	            CHECK(std::isfinite(expected[j]) && expected[j] < 9.0e15,
125	                  "stencil expected < 2^53");
126	            CHECK(std::fmod(expected[j] * 8.0, 1.0) == 0.0,
127	                  "stencil expected on exact 1/8 grid");
128	        }
129	        // Order independence: reverse-r accumulation must give the same
130	        // bits (proves the hw accumulation order cannot cause a mismatch).
131	        const double *s = src.data() + coord * stride * B_TILE;
132	        double rev[B_TILE] = {};
133	        for (size_t rr = RADIUS; rr >= 1; --rr) {
134	            std::ptrdiff_t off = (std::ptrdiff_t)(rr * stride) * B_TILE;
135	            for (size_t j = 0; j < B_TILE; ++j) {
136	                double delta = 0.0;
137	                if (coord >= rr) delta += s[-off + (std::ptrdiff_t)j];
138	                if (coord + rr < extent) delta += s[+off + (std::ptrdiff_t)j];
139	                rev[j] += 0.125 * delta;
140	            }
141	        }
142	        for (size_t j = 0; j < B_TILE; ++j) {
143	            CHECK((rev[j] * (double)ITER) == expected[j],
144	                  "stencil expected order-independent");
145	        }
146	    }
147	}
