3	 *
4	 * Registers the simulator deviations that the dual-channel kernels must
5	 * avoid, and exercises the instruction families those kernels rely on:
6	 *
7	 *   P1  DUP  (imm broadcast)          — kernels use svdup_* intrinsics
8	 *   P2  MOV  (vector imm, z-regs)     — KNOWN gem5 DEVIATION: writes are
9	 *                                       lost, st1d reads back 0.0 (F3)
10	 *   P3  predicated merging FMLA       — svmla detection semantics
11	 *   P4  ld1d/st1d full-VL integrity   — lane count must equal svcntd()
12	 *   P5  SME ZA storage round-trip     — SMSTART/ZERO/ZA-readout/SMSTOP
13	 *   P6  SME FMOPA vs fmaf             — gem5 fplib mul+add double rounding
14	 *                                       (F4): deviation is recorded, not
15	 *                                       judged (kernel golden = in-sim
16	 *                                       baseline for FMOPA paths)
17	 *
18	 * Build (clang required for SME asm):
19	 *   clang -static -O2 -march=armv9-a+sve+sme -o sve_sme_semantics sve_sme_semantics.c
20	 * Run (gem5, VL/SVL = 512-bit for the sve512/SME kernels):
21	 *   gem5.opt configs/se/arm_chaos.py --cmd <bin> --sve_vl 4 --sme_vl 4
22	 */
23	#include <arm_sve.h>
24	#include <stdio.h>
25	#include <stdint.h>
26	#include <math.h>
27	
28	static int deviations = 0;
29	
30	#define REPORT(name, ok, detail)                                          \
31	    do {                                                                  \
32	        printf("%-28s %-7s %s\n", name, (ok) ? "PASS" : "DEVIATION",      \
33	               detail);                                                   \
34	        if (!(ok)) ++deviations;                                          \
35	    } while (0)
36	
37	/* KNOWN deviations (already registered in the plan, e.g. F3) are reported
38	 * but do not affect the exit code — the suite fails only on NEW ones. */
39	#define REPORT_KNOWN(name, ok, detail)                                    \
40	    do {                                                                  \
41	        printf("%-28s %-7s %s\n", name, (ok) ? "PASS" : "DEVIATION",      \
42	               detail);                                                   \
43	    } while (0)
44	
45	int main(void)
46	{
47	    const uint64_t lanes = svcntd();
48	    printf("VL = %lu bytes (%lu f64 lanes); ", svcntb(), lanes);
49	    printf("SVL probe below\n");
50	
51	    /* ---- P1: DUP immediate broadcast (what svdup_* compiles to) ---- */
52	    {
53	        double out[32];
54	        svfloat64_t v = svdup_f64(7.5);
55	        svst1_f64(svptrue_b64(), out, v);
56	        int ok = 1;
57	        for (uint64_t i = 0; i < lanes && i < 32; ++i)
58	            ok &= (out[i] == 7.5);
59	        REPORT("P1 dup_f64 imm", ok, "all lanes == 7.5");
60	    }
61	
62	    /* ---- P2: MOV vector immediate — EXPECTED DEVIATION (F3) ---- */
63	    {
64	        double out[32] = {0};
65	        asm volatile(
66	            "ptrue p0.d\n"
67	            "mov z3.d, #1\n"
68	            "st1d z3.d, p0, [%0]\n"
69	            :: "r"(out) : "z3", "p0", "memory");
70	        int moved = 1;
71	        for (uint64_t i = 0; i < lanes && i < 32; ++i)
72	            moved &= (out[i] == 1.0);
73	        REPORT_KNOWN("P2 mov z.d,#imm (KNOWN)", moved,
74	               moved ? "writes survive (deviation gone)"
75	                     : "writes LOST — kernels must use dup (F3 confirmed)");
76	    }
77	
78	    /* ---- P3: predicated merging FMLA over full VL ---- */
79	    {
80	        double a[32], b[32], acc[32];
81	        for (int i = 0; i < 32; ++i) { a[i] = i + 1; b[i] = 2.0; }
82	        svfloat64_t va = svld1_f64(svptrue_b64(), a);
83	        svfloat64_t vb = svld1_f64(svptrue_b64(), b);
84	        svfloat64_t vc = svdup_f64(1.0);
85	        vc = svmla_f64_m(svptrue_b64(), vc, va, vb);
86	        svst1_f64(svptrue_b64(), acc, vc);
87	        int ok = 1;
88	        for (uint64_t i = 0; i < lanes && i < 32; ++i)
89	            ok &= (acc[i] == 1.0 + (i + 1) * 2.0);
90	        REPORT("P3 fmla merging (ptrue)", ok, "acc = 1 + (i+1)*2 all lanes");
91	    }
92	
93	    /* ---- P4: ld1d/st1d round-trip integrity at full VL ---- */
94	    {
95	        double a[32], r[32];
96	        for (int i = 0; i < 32; ++i) a[i] = 0.5 * i + 0.25;
97	        svst1_f64(svptrue_b64(), r, svld1_f64(svptrue_b64(), a));
98	        int ok = 1;
99	        for (uint64_t i = 0; i < lanes && i < 32; ++i)
100	            ok &= (r[i] == a[i]);
101	        char d[64];
102	        snprintf(d, sizeof d, "%lu lanes bit-identical", lanes);
103	        REPORT("P4 ld1d/st1d roundtrip", ok, d);
104	    }
105	
106	    /* ---- P5: SME ZA storage round-trip (SVL-dependent) ---- */
107	    {
108	        /* ONE tile slice via ZERO + readout. SME asm: smstart za; zero
109	         * {za}; write one f64 slice via MOV to ZA is arch-encoded — the
110	         * portable probe uses the f64 tile MOVA-free path: zero then read
111	         * a slice with za readout must give 0 everywhere; then a full
112	         * FMOPA round-trip (P6) covers non-zero storage. */
113	        int64_t svl = 0, zero_ok = 1;
114	        asm volatile(
115	            "smstart za\n"
116	            "rdsvl %0, #1\n"
117	            "zero {za}\n"
118	            "smstop za\n"
119	            : "=r"(svl));
120	        REPORT("P5 SME zero+rdsvl", svl > 0 && (svl & (svl - 1)) == 0,
121	               "rdsvl power-of-2 bytes > 0");
122	        (void)zero_ok;
123	    }
124	
125	    /* ---- P6: SME FMOPA (f32) vs single-rounding fmaf (F4 record) ---- */
126	    {
127	        /* One FMOPA za0.s over the full SVL: tile row 0 = a[0] x b[.].
128	         * gem5 implements FMOPA as fplibMul + fplibAdd (double rounding);
129	         * hardware is single-rounding FMA. Recorded, not judged. */
130	        float a[32], b[32], out[32];
131	        for (int i = 0; i < 32; ++i) { a[i] = 0.1f * i + 0.05f; b[i] = 0.7f - 0.02f * i; }
132	        asm volatile(
133	            "smstart sm\n\t"
134	            "smstart za\n\t"
135	            "zero {za}\n\t"
136	            "ptrue p0.s\n\t"
137	            "ptrue p1.s\n\t"
138	            "ld1w {z0.s}, p0/z, [%1]\n\t"
139	            "ld1w {z1.s}, p0/z, [%2]\n\t"
140	            "fmopa za0.s, p0/m, p1/m, z0.s, z1.s\n\t"
141	            "mov w12, #0\n\t"
142	            "st1w {za0h.s[w12, 0]}, p0, [%0]\n\t"
143	            "smstop za\n\t"
144	            "smstop sm\n\t"
145	            : : "r"(out), "r"(a), "r"(b)
146	            : "z0", "z1", "w12", "p0", "p1", "memory");
147	        float ref[32];
148	        for (int i = 0; i < 32; ++i) ref[i] = fmaf(a[0], b[i], 0.0f);
149	        const uint64_t svl_lanes = (uint64_t)svcntw();
150	        int bitexact = 1;
151	        for (uint64_t i = 0; i < svl_lanes && i < 32; ++i)
152	            bitexact &= (out[i] == ref[i]);
153	        char d[160];
154	        snprintf(d, sizeof d,
155	                 "svl f32 lanes=%lu fmopa==fmaf bitexact=%d out[0]=%.9g "
156	                 "ref=%.9g (diff => F4 double-rounding)", svl_lanes, bitexact,
157	                 out[0], ref[0]);
158	        REPORT("P6 fmopa f32 vs fmaf (F4)", 1 /* recorded, not judged */, d);
159	    }
160	
161	    printf("RESULT: %d deviation(s) beyond the recorded ones\n", deviations);
162	    return deviations ? 2 : 0;
163	}

