38	// Type-punning helper (mirrors the original).
39	static inline uint32_t bits_of(float f)
40	{
41	    uint32_t u;
42	    std::memcpy(&u, &f, sizeof(u));
43	    return u;
44	}
45	static inline uint64_t bits_of(double d)
46	{
47	    uint64_t u;
48	    std::memcpy(&u, &d, sizeof(u));
49	    return u;
