52	// Number of special values in the sweep table (per type).
53	static constexpr int NUM_SPECIALS = 16;
54	
55	/* Indices 0..11 are the fixed IEEE-754 specials — the test's semantic
56	 * core, kept constant. Indices 12..15 are finite values drawn from the
57	 * framework RNG (re-seeded per fracture fragment), so the cartesian
58	 * sweep covers fresh finite-operand combinations on every fragment
59	 * instead of replaying one fixed table (PR #234 review, greptile
60	 * 4254737399). Random values are finite and non-NaN, but triples that
61	 * mix them with the table's NaN/Inf specials can still produce NaN
62	 * results — those are compared class-only; every non-NaN result is
63	 * byte-exact-compared (see sweep_f32_sve/sweep_f64_sve). */
64	static void build_specials_f32(float t[NUM_SPECIALS])
65	{
66	    t[0]  = NAN;
67	    t[1]  = __builtin_nansf("");
68	    t[2]  = INFINITY;
69	    t[3]  = -INFINITY;
70	    t[4]  = 0.0f;
71	    t[5]  = -0.0f;
72	    t[6]  =  std::numeric_limits<float>::denorm_min();
73	    t[7]  = -std::numeric_limits<float>::denorm_min();
74	    t[8]  =  std::numeric_limits<float>::max();
75	    t[9]  = -std::numeric_limits<float>::max();
76	    t[10] =  std::numeric_limits<float>::min();
77	    t[11] = -std::numeric_limits<float>::min();
78	    for (int i = 12; i < NUM_SPECIALS; ++i)
79	        t[i] = (random32() & 1 ? -1.0f : 1.0f) * frandomf_scale(1.0f);
80	}
81	
82	static void build_specials_f64(double t[NUM_SPECIALS])
83	{
84	    t[0]  = NAN;
85	    t[1]  = __builtin_nans("");
86	    t[2]  = INFINITY;
87	    t[3]  = -INFINITY;
88	    t[4]  = 0.0;
89	    t[5]  = -0.0;
90	    t[6]  =  std::numeric_limits<double>::denorm_min();
91	    t[7]  = -std::numeric_limits<double>::denorm_min();
92	    t[8]  =  std::numeric_limits<double>::max();
93	    t[9]  = -std::numeric_limits<double>::max();
94	    t[10] =  std::numeric_limits<double>::min();
95	    t[11] = -std::numeric_limits<double>::min();
96	    for (int i = 12; i < NUM_SPECIALS; ++i)
97	        t[i] = (random32() & 1 ? -1.0 : 1.0) * frandom_scale(1.0);
98	}
