116	// Sweep the float32 FMA over the full special-value cartesian product on
117	// SVE lanes; every lane of the broadcast vector is byte-compared.
118	static int sweep_f32_sve(const float a_t[NUM_SPECIALS],
119	                         const float b_t[NUM_SPECIALS],
120	                         const float c_t[NUM_SPECIALS],
121	                         float &out_a, float &out_b, float &out_c,
122	                         float &out_hw, float &out_sw)
123	{
124	    int mismatches = 0;
125	    float hw_lane = 0, sw_lane = 0;
126	    const int lanes32 = svcntw();
127	    float hwv[32];   /* 最大支持 VL 1024bit (32 lanes) */
128	
129	    for (int i = 0; i < NUM_SPECIALS; ++i) {
130	        for (int j = 0; j < NUM_SPECIALS; ++j) {
131	            for (int k = 0; k < NUM_SPECIALS; ++k) {
132	                float a = a_t[i], b = b_t[j], c = c_t[k];
133	
134	                /* Hardware: svmla_f32_x (c + a*b, single rounding). Broadcast
135	                 * into a full SVE vector; ALL lanes checked (per-lane SDC). */
136	                svbool_t pg = svptrue_b32();
137	                svfloat32_t va = svdup_f32(a);
138	                svfloat32_t vb = svdup_f32(b);
139	                svfloat32_t vc = svdup_f32(c);
140	                svfloat32_t vd = svmla_f32_x(pg, vc, va, vb);
141	                svst1_f32(pg, hwv, vd);
142	
143	                /* Software reference: fmaf (single rounding, IEEE-754). */
144	                sw_lane = fmaf(a, b, c);
145	                uint32_t sw_bits = bits_of(sw_lane);
146	
147	                /* Per-lane compare: NaN class-only for NaN results,
148	                 * byte-exact otherwise (1-bit ULP flip is caught). */
149	                for (int lane = 0; lane < lanes32 && lane < 32; ++lane) {
150	                    hw_lane = hwv[lane];
151	                    bool hw_nan = std::isnan(hw_lane);
152	                    bool sw_nan = std::isnan(sw_lane);
153	                    /* NaN class-only: IEEE-754 leaves NaN payload
154	                     * propagation implementation-defined (hardware svmla
155	                     * ORs the input NaN payloads, libm fma forwards the
156	                     * first operand's) - only NaN-ness is checked when
157	                     * either side is NaN; all non-NaN results (incl. -0.0
158	                     * sign flips, the SDC signal) stay byte-exact. */
159	                    bool lane_ok = (hw_nan || sw_nan) ? (hw_nan && sw_nan)
160	                                                      : (bits_of(hw_lane) == sw_bits);
161	                    if (!lane_ok) {
162	                        if (mismatches == 0) {
163	                            out_a = a; out_b = b; out_c = c;
164	                            out_hw = hw_lane; out_sw = sw_lane;
165	                        }
166	                        ++mismatches;
167	                    }
168	                }
169	            }
170	        }
171	    }
172	    return mismatches;
173	}
