5	 *
6	 * @test @b sve512_stencil_axis_arm
7	 * @parblock
8	 * SCF/stencil axis-kernel SDC trigger replicator — verbatim port of the
9	 * standalone example.cpp reproducer for the cn23154 NUMA3 virtual-address
10	 * path fault. Hot-loop structure preserved exactly, including the
11	 * svdup_f64(coeff[r]) coefficient loads (ld1rd replicate-load codegen
12	 * under clang — one of the fault-window instructions), the dual-vector
13	 * svmla_x chain, the temp/res0 spacing assignments, the full unroll
14	 * pragma, the memory-resident file-scope loop counter and the
15	 * per-iteration VA[63:48] canary on the accumulator's stack slot.
16	 *
17	 * Math (per the field diagnosis, production stencil_kernel.h radius=6):
18	 * src holds per-element random small integers (1..256) drawn from the
19	 * framework RNG — re-seeded per fracture fragment, so every fragment
20	 * gets fresh inputs — and coeff[r] = 0.125. Per call per lane j the
21	 * increment is sum over r of 0.125 * (src[coord-r][j] +
22	 * src[coord+r][j]): every term is an exact multiple of 1/8 and the
23	 * per-call increment stays below 768, so the expected result — the
24	 * scalar reference in test_run scaled by iterations — stays on the
25	 * exact 1/8 grid below 2^53: order-independent, bit-exact equality.
26	 * (The original standalone used the fixed src[i] = i%16+1, where the
27	 * expectation reduced to 1.5 * iterations * (j+1); its stale RADIUS=4
28	 * expectation iterations*(j+1) was a software false positive — 5
29	 * bit-identical reruns, identical results on healthy cores — fixed per
30	 * the report's follow-up item 7.1.)
31	 *
32	 * Framework adaptations (each forced by the harness, structure-neutral):
33	 *   - main() -> test_init/test_run/test_cleanup; src and s_base are set
34	 *     up once in init and shared read-only across CPU threads;
35	 *   - the file-scope loop counter j is thread_local: sdcshield runs one
36	 *     test_run per CPU concurrently and a plain global would be a
37	 *     cross-thread data race (false FAILs); TLS keeps it memory-resident
38	 *     exactly as the original intended;
39	 *   - coeff stays a stack-local table in test_run (the ld1rd source);
40	 *   - the canary's printf -> log_warning;
41	 *   - #pragma clang loop unroll(full) guarded by __clang__ (GCC -Wall
42	 *     warns on the unknown pragma; clang builds — the field toolchain —
43	 *     see it unchanged);
44	 *   - per-lane results are logged only on mismatch; chrono timing
45	 *     dropped (the framework times tests itself).
46	 *
47	 * Requires 512-bit SVE (svcntd() == 8); other SVE vector lengths return
48	 * a clean EXIT_SKIP, non-SVE CPUs are skipped by the framework's
49	 * compiler-feature gate. Built only on aarch64.
50	 * @endparblock
51	 */
52	
53	#include <sandstone.h>
54	#include <cinttypes>
55	#include <cstdint>
56	#include <cstddef>
57	#include <cstring>
58	#include <memory>
59	#include <vector>
