67	using std::size_t;
68	using std::ptrdiff_t;
69	
70	constexpr size_t RADIUS = 6;
71	constexpr size_t B_TILE = 16;
72	
73	// Grid geometry (shared between init and run).
74	static constexpr size_t coord = 10;
75	static constexpr size_t extent = 56;
76	static constexpr size_t stride = 64;
77	static constexpr size_t iterations = 100'000'000;
78	
79	// Memory-resident loop counter, as in the original (file-scope, so it is
80	// not register-allocated). thread_local because the framework runs one
81	// test_run per CPU concurrently — a plain global would race across
82	// threads; TLS preserves the memory-resident property per thread.
83	static thread_local size_t j;
84	
85	struct SveStencilAxisData {
86	    // [extent][stride][B_TILE] grid, filled with (i % 16) + 1 per tile.
87	    std::vector<double> src;
88	    // Points at the coord=10 layer's first tile (negative offsets legal).
89	    const double *s_base = nullptr;
90	};
91	
92	#ifdef __aarch64__
93	
94	// Type-punning helper (mirrors fsu_byteexact_arm / fpu_special_values_sve).
95	static inline uint64_t bits_of(double d)
96	{
97	    uint64_t u;
98	    std::memcpy(&u, &d, sizeof(u));
99	    return u;
100	}
101	
102	inline void axis_generic_16x2(
103	    const double* s_base, const size_t coord,
104	    const size_t extent, const size_t stride,
105	    const svbool_t ptrue, const double* coeff,
106	    svfloat64_t& res0, svfloat64_t& res1)
107	{
108	#if defined(__clang__)
109	#pragma clang loop unroll(full)
110	#endif
111	    for (size_t r = 1; r <= RADIUS; ++r) {
112	        const ptrdiff_t off = static_cast<ptrdiff_t>(r * stride) * B_TILE;
113	        const svfloat64_t c = svdup_f64(coeff[r]);
114	
115	        if (coord >= r) {
116	            const double* n = s_base - off;
117	            res0 = svmla_x(ptrue, res0, svld1(ptrue, n), c);
118	            res1 = svmla_x(ptrue, res1, svld1(ptrue, n + 8), c);
119	        }
120	        if (coord + r < extent) {
121	            const double* n = s_base + off;
122	            res0 = svmla_x(ptrue, res0, svld1(ptrue, n), c);
123	            res1 = svmla_x(ptrue, res1, svld1(ptrue, n + 8), c);
124	        }
125	    }
126	}
